import pandas as pd
import numpy as np

# Load data
df = pd.read_csv('chunks_csv/moran_local_2022_ghg.csv')
adjacency_df = pd.read_csv('chunks_csv/borough_adjacency.csv')

# Compute neighborhood GHG values
neighborhood_values = {}
for index, row in adjacency_df.iterrows():
    borough = row['borough']
    neighbors = adjacency_df.loc[adjacency_df['neighbor'] == borough, 'borough'].tolist()
    neighborhood_values[borough] = np.mean(df.loc[df['borough'].isin(neighbors), 'GHG_value'])

# Classify boroughs as HOT SPOT or COLD SPOT
classifications = {}
for index, row in df.iterrows():
    borough = row['borough']
    if row['GHG_value'] > neighborhood_values[borough]:
        classifications[borough] = 'HOT SPOT'
    elif row['GHG_value'] < neighborhood_values[borough]:
        classifications[borough] = 'COLD SPOT'
    else:
        classifications[borough] = 'NEUTRAL'

# Compute statistical significance
significant_boroughs = {}
for borough, classification in classifications.items():
    if classification != 'NEUTRAL':
        values = df.loc[df['borough'] == borough, 'GHG_value'].values
        neighborhood_values = df.loc[df['borough'].isin(adjacency_df.loc[adjacency_df['borough'] == borough, 'neighbor']), 'GHG_value'].values
        test_statistic = np.mean(values) - np.mean(neighborhood_values)
        p_value = 0
        for _ in range(500):
            shuffled_values = np.random.permutation(values)
            shuffled_neighborhood_values = np.random.permutation(neighborhood_values)
            shuffled_test_statistic = np.mean(shuffled_values) - np.mean(shuffled_neighborhood_values)
            p_value += (shuffled_test_statistic >= test_statistic)
        p_value /= 500
        if p_value < 0.05:
            significant_boroughs[borough] = test_statistic

# Identify significant HOT SPOTS and COLD SPOTS
significant_classifications = {}
for borough, classification in classifications.items():
    if borough in significant_boroughs:
        significant_classifications[borough] = classification

# List identified boroughs
identified_boroughs = []
for borough, classification in significant_classifications.items():
    identified_boroughs.append(f'{borough} ({classification}, statistical method={significant_boroughs[borough]})')

# Print results
data_points_used = len(df)
print(f'data_points_used = {data_points_used}')
print(f'FINAL ANSWER: {", ".join(identified_boroughs)}')
